<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { api, getErrorMessage } from '@/api/http'
import type { Analytics, ApiResponse, Movement, Paged, Product } from '@/types/api'
import PageHeader from '@/components/PageHeader.vue'
import InventoryChart from '@/components/InventoryChart.vue'
import { formatQuantity, formatDateTime, kindLabel, localDate, productLabel, matchesProduct } from '@/utils/inventory'
import { productRowStyle, productStyle, productTone } from '@/utils/productColors'
const today=localDate(), from=ref(today.slice(0,8)+'01'), to=ref(today), productIds=ref<string[]>([]), products=ref<Product[]>([]), data=ref<Analytics>(), loading=ref(false), page=ref(1)
const search=ref(''), view=ref('cards'), onlyLow=ref(false), sort=ref('name')
const ledger=ref<Movement[]>([]), ledgerOpen=ref(false), ledgerPage=ref(1), ledgerTotal=ref(0), ledgerProduct=ref(''), ledgerLoading=ref(false)
const rows=computed(()=>data.value?.rows??[])
const productSearch=ref('')
const options=computed(()=>products.value.filter(p=>matchesProduct(p,productSearch.value)))
function filterProducts(query:string){productSearch.value=query}
function resetSearch(visible:boolean){if(!visible)productSearch.value=''}
const oneUnit=computed(()=>rows.value.length>0 && new Set(rows.value.map(x=>x.unit)).size===1)
const displayUnit=computed(()=>oneUnit.value?rows.value[0]!.unit:'')
const sum=(key:'inbound'|'outbound'|'netChange'|'currentQuantity'|'inboundCount'|'outboundCount')=>rows.value.reduce((a,r)=>a+r[key],0)
const metrics=computed(()=>oneUnit.value?[
  {title:'当前结存',value:sum('currentQuantity'),unit:displayUnit.value,caption:'此刻库存，不受日期区间影响',tone:'blue'},
  {title:'期间入库',value:sum('inbound'),unit:displayUnit.value,caption:'已完成的正常入库',tone:'green'},
  {title:'期间出库',value:sum('outbound'),unit:displayUnit.value,caption:'已完成的正常出库',tone:'purple'},
  {title:'期间净变化',value:sum('netChange'),unit:displayUnit.value,caption:'入库 − 出库 ＋ 库存调整',tone:'amber'},
]:[
  {title:'商品种类',value:rows.value.length,unit:'种',caption:'当前查询范围内的商品',tone:'blue'},
  {title:'库存告急',value:rows.value.filter(x=>x.isLowStock).length,unit:'种',caption:'低于各自设置的预警值',tone:'red'},
  {title:'期间入库',value:sum('inboundCount'),unit:'次',caption:'不同单位按操作次数查看',tone:'green'},
  {title:'期间出库',value:sum('outboundCount'),unit:'次',caption:'不含导入和盘库调整',tone:'purple'},
])
const filtered=computed(()=>rows.value.filter(p=>productLabel(p).toLowerCase().includes(search.value.toLowerCase())&&(!onlyLow.value||p.isLowStock)).sort((a,b)=>{
  if(sort.value==='low'&&a.isLowStock!==b.isLowStock)return a.isLowStock?-1:1
  if(sort.value==='stock')return a.unit.localeCompare(b.unit)||a.currentQuantity-b.currentQuantity
  return a.name.localeCompare(b.name,'zh-CN')||a.unit.localeCompare(b.unit)||a.productSpecification.localeCompare(b.productSpecification)
}))
const shown=computed(()=>filtered.value.slice((page.value-1)*12,page.value*12))
const trend=computed(()=>({tooltip:{trigger:'axis',renderMode:'richText'},legend:{bottom:0,data:['入库','出库']},grid:{left:12,right:20,top:28,bottom:40,containLabel:true},xAxis:{type:'category',boundaryGap:false,data:data.value?.trend.map(x=>x.date.slice(5))??[],axisLine:{lineStyle:{color:'#d6e5ee'}},axisLabel:{color:'#6d8292'}},yAxis:{type:'value',name:oneUnit.value?displayUnit.value:'操作次数',minInterval:1,splitLine:{lineStyle:{color:'#edf2f6'}}},series:[
  {name:'入库',type:'line',smooth:false,symbolSize:5,data:data.value?.trend.map(x=>oneUnit.value?x.inbound:x.inboundCount),itemStyle:{color:'#438bab'},lineStyle:{width:3},areaStyle:{color:'#438bab',opacity:.07}},
  {name:'出库',type:'line',smooth:false,symbolSize:5,data:data.value?.trend.map(x=>oneUnit.value?x.outbound:x.outboundCount),itemStyle:{color:'#a38ac7'},lineStyle:{width:3}}
]}))
const health=computed(()=>[
  {name:'库存告急',value:rows.value.filter(x=>x.isLowStock).length,itemStyle:{color:'#cb7680'}},
  {name:'零库存（非告急）',value:rows.value.filter(x=>!x.isLowStock&&x.currentQuantity===0).length,itemStyle:{color:'#d4ab68'}},
  {name:'有库存（非告急）',value:rows.value.filter(x=>!x.isLowStock&&x.currentQuantity>0).length,itemStyle:{color:'#75b6ad'}},
])
const donut=computed(()=>({tooltip:{trigger:'item',renderMode:'richText',formatter:'{b}：{c} 种'},legend:{show:false},series:[{type:'pie',radius:['63%','82%'],center:['50%','50%'],label:{show:false},data:health.value.filter(x=>x.value>0),itemStyle:{borderRadius:6,borderWidth:3,borderColor:'#fff'}}]}))
let loadSequence=0
async function load(){const seq=++loadSequence;loading.value=true;try{const result=(await api.post<ApiResponse<Analytics>>('/api/v1/analytics/query',{from:from.value,to:to.value,productIds:[...productIds.value]})).data.data;if(seq===loadSequence){data.value=result;page.value=1}}catch(e){if(seq===loadSequence)ElMessage.error(getErrorMessage(e))}finally{if(seq===loadSequence)loading.value=false}}
function preset(days:number){to.value=localDate();from.value=days===0?to.value.slice(0,8)+'01':localDate(new Date(Date.now()-(days-1)*86400000));void load()}
let ledgerSequence=0
async function showLedger(id?:string){if(id){ledgerProduct.value=id;ledgerPage.value=1;ledger.value=[]}ledgerOpen.value=true;ledgerLoading.value=true;const seq=++ledgerSequence;try{const r=(await api.get<ApiResponse<Paged<Movement>>>('/api/v1/movements',{params:{productId:ledgerProduct.value,page:ledgerPage.value}})).data.data;if(seq===ledgerSequence){ledger.value=r.items;ledgerTotal.value=r.total}}catch(e){ElMessage.error(getErrorMessage(e))}finally{if(seq===ledgerSequence)ledgerLoading.value=false}}
const ledgerTitle=computed(()=>products.value.find(p=>p.id===ledgerProduct.value)?.name??'商品')
onMounted(async()=>{try{products.value=(await api.get<ApiResponse<Product[]>>('/api/v1/products/')).data.data}catch(e){ElMessage.error(getErrorMessage(e))}await load()})
</script>
<template><div class="page-shell analytics-page">
  <PageHeader eyebrow="INVENTORY INSIGHTS" title="数据看板" description="看清每种商品的库存，以及这段时间进了多少、出了多少。"><el-button type="primary" :loading="loading" @click="load">刷新看板</el-button></PageHeader>
  <section class="panel filter-panel"><div class="filter-top"><span class="filter-title">查看范围</span><div class="date-presets"><el-button size="small" @click="preset(1)">今天</el-button><el-button size="small" @click="preset(7)">近 7 天</el-button><el-button size="small" @click="preset(30)">近 30 天</el-button><el-button size="small" @click="preset(0)">本月</el-button></div></div>
    <div class="filter-grid"><el-date-picker v-model="from" type="date" value-format="YYYY-MM-DD" placeholder="开始日期" aria-label="开始日期"/><span class="date-to">至</span><el-date-picker v-model="to" type="date" value-format="YYYY-MM-DD" placeholder="结束日期" aria-label="结束日期"/><el-select class="product-filter product-picker" v-model="productIds" multiple collapse-tags collapse-tags-tooltip :max-collapse-tags="1" filterable :filter-method="filterProducts" @visible-change="resetSearch" clearable placeholder="全部商品（支持多选、搜索备注）" aria-label="商品筛选" popper-class="product-options"><el-option v-for="p in options" :key="p.id" :label="productLabel(p)" :value="p.id" :style="productStyle(p.name)"><span class="product-name">{{p.name}}</span><span class="product-spec"> · {{p.productSpecification}} · {{p.rawMaterialSpecification}} · </span><b class="product-unit">{{p.unit}}</b><b v-if="p.note" class="product-note"> · {{p.note}}</b></el-option></el-select><el-button type="primary" :loading="loading" @click="load">查询</el-button></div>
    <div v-if="data" class="applied-range">正在显示 {{data.from}} 至 {{data.to}} 的已过账数据 <span>{{oneUnit?'数量单位：'+displayUnit:'跨单位概览：按操作次数统计，不混合累加数量'}}</span></div>
  </section>
  <div class="insight-metrics" v-loading="loading"><article v-for="m in metrics" :key="m.title" class="metric" :class="'metric-'+m.tone"><span>{{m.title}}</span><div><strong>{{formatQuantity(m.value)}}</strong><small>{{m.unit}}</small></div><p>{{m.caption}}</p></article></div>
  <div class="chart-grid">
    <section class="panel trend-panel"><div class="section-title"><div><h2>出入库趋势</h2><p class="muted">按日查看{{oneUnit?'数量':'操作次数'}}，库存导入和盘库调整单独在商品明细列示。</p></div><span class="chart-tag">{{oneUnit?displayUnit:'次 / 日'}}</span></div><InventoryChart v-if="rows.length" :option="trend" :height="280"/><el-empty v-else description="当前范围没有商品"/></section>
    <section class="panel health-panel"><h2>当前库存状态</h2><div v-if="rows.length" class="donut-wrap"><InventoryChart :option="donut" :height="210"/><div class="donut-total"><strong>{{rows.length}}</strong><span>种商品</span></div></div><el-empty v-else description="暂无商品"/><div class="health-legend"><div v-for="h in health" :key="h.name"><span><i :style="{backgroundColor:h.itemStyle.color}"/>{{h.name}}</span><strong>{{h.value}} 种</strong></div></div></section>
  </div>
  <section class="panel product-overview"><div class="section-title"><div><h2>商品库存一览</h2><p class="muted">结存为此刻库存 · 净变化 = 入库 − 出库 + 库存调整</p></div><el-radio-group v-model="view" size="small" aria-label="展示方式"><el-radio-button value="cards">卡片</el-radio-button><el-radio-button value="table">明细表</el-radio-button></el-radio-group></div>
    <div class="toolbar"><el-input v-model="search" clearable placeholder="搜索名称、规格或备注" @input="page=1"/><el-select v-model="sort" aria-label="商品排序" @change="page=1"><el-option label="按商品名称" value="name"/><el-option label="预警商品优先" value="low"/><el-option label="同单位库存从低到高" value="stock"/></el-select><el-checkbox v-model="onlyLow" @change="page=1">只看库存告急</el-checkbox><span class="muted right">{{filtered.length}} 种商品</span></div>
    <div v-if="view==='cards' && shown.length" class="product-cards"><article v-for="p in shown" :key="p.id" class="product-card" :style="productStyle(p.name)"><div class="product-card-title"><strong class="product-name">{{p.name}}</strong><span class="color-dot" :style="{backgroundColor:productTone(p.name).accent}" :title="productTone(p.name).label"/></div><p class="card-spec product-spec">{{p.productSpecification || '无产品规格'}} · {{p.rawMaterialSpecification || '无原料规格'}}</p><p class="card-note product-note">备注：{{p.note || '无'}}</p>
      <div class="card-balance"><div><span>当前结存</span><strong>{{formatQuantity(p.currentQuantity)}}<small class="product-unit">{{p.unit}}</small></strong></div><el-tag v-if="p.isLowStock" type="danger">库存告急</el-tag><el-tag v-else-if="!p.isActive" type="info">已停用</el-tag><el-tag v-else-if="p.currentQuantity===0" type="warning">零库存</el-tag></div>
      <div class="card-flow"><div><span>期间入库</span><b>{{formatQuantity(p.inbound)}}</b></div><div><span>期间出库</span><b>{{formatQuantity(p.outbound)}}</b></div><div><span>净变化</span><b :class="p.netChange<0?'negative':'positive'">{{p.netChange>0?'+':''}}{{formatQuantity(p.netChange)}}</b></div></div><div class="card-bottom"><small>库存调整 {{p.adjustment>0?'+':''}}{{formatQuantity(p.adjustment)}}</small><el-button type="primary" size="small" @click="showLedger(p.id)">查看流水</el-button></div>
    </article></div>
    <el-table class="product-typography" v-else-if="view==='table'" :data="shown" :row-style="productRowStyle"><el-table-column label="商品" min-width="260"><template #default="s"><strong class="product-name">{{s.row.name}}</strong><div class="spec product-spec">{{s.row.productSpecification}} · {{s.row.rawMaterialSpecification}}</div><div class="product-note">{{s.row.note || '无备注'}}</div></template></el-table-column><el-table-column prop="unit" class-name="product-unit" label="单位" width="120"/><el-table-column label="期间入库" width="110"><template #default="s">{{formatQuantity(s.row.inbound)}}</template></el-table-column><el-table-column label="期间出库" width="110"><template #default="s">{{formatQuantity(s.row.outbound)}}</template></el-table-column><el-table-column label="库存调整" width="110"><template #default="s">{{formatQuantity(s.row.adjustment)}}</template></el-table-column><el-table-column label="净变化" width="110"><template #default="s">{{formatQuantity(s.row.netChange)}}</template></el-table-column><el-table-column label="当前结存" width="115"><template #default="s"><strong>{{formatQuantity(s.row.currentQuantity)}}</strong></template></el-table-column><el-table-column label="操作" width="110" fixed="right"><template #default="s"><el-button type="primary" size="small" @click="showLedger(s.row.id)">查看流水</el-button></template></el-table-column></el-table><el-empty v-else description="没有符合筛选条件的商品"/>
    <el-pagination v-model:current-page="page" :page-size="12" :total="filtered.length" layout="total, prev, pager, next"/>
  </section>
  <el-dialog v-model="ledgerOpen" :title="ledgerTitle+' · 全部库存流水'" width="1050px"><p class="muted">展示该商品全部历史流水，不受看板日期筛选限制。</p><el-table :data="ledger" :row-style="productRowStyle" v-loading="ledgerLoading"><el-table-column label="时间" width="175"><template #default="s">{{formatDateTime(s.row.postedAt)}}</template></el-table-column><el-table-column label="类型" width="85"><template #default="s">{{kindLabel(s.row.kind)}}</template></el-table-column><el-table-column label="变化" width="110"><template #default="s">{{formatQuantity(s.row.quantityChange)}}</template></el-table-column><el-table-column label="变动后结存" width="125"><template #default="s">{{formatQuantity(s.row.quantityAfter)}}</template></el-table-column><el-table-column prop="userName" label="操作人" width="100"/><el-table-column prop="note" label="备注" min-width="180"/></el-table><el-pagination v-model:current-page="ledgerPage" :page-size="30" :total="ledgerTotal" layout="total, prev, pager, next" @current-change="showLedger()"/></el-dialog>
</div></template>
<style scoped>
.filter-panel{padding:20px 24px}.filter-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;gap:12px}.filter-title{font-weight:700}.date-presets{display:flex;gap:6px}.date-presets .el-button{margin:0}.filter-grid{display:grid;grid-template-columns:160px 20px 160px minmax(240px,1fr) 70px;gap:12px;align-items:center}.filter-grid :deep(.el-date-editor),.filter-grid .el-select{width:100%}.date-to{text-align:center;color:#758a9b}.applied-range{margin-top:15px;font-size:12px;color:#587285;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}.insight-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px}.metric{padding:22px;border:1px solid #d9e9f3;border-radius:16px;background:#fff;position:relative;border-top:3px solid #72a5c1}.metric>span{font-size:14px;font-weight:600;color:#4d6b80}.metric>div{display:flex;align-items:baseline;gap:10px;margin:13px 0 9px}.metric strong{font-size:34px;letter-spacing:-1px;font-variant-numeric:tabular-nums}.metric small{font-size:13px;color:#607b8c}.metric p{font-size:12px;color:#748c9b;margin:0;line-height:1.5}.metric-green{border-top-color:#79b3a6}.metric-purple{border-top-color:#ab96c9}.metric-red{border-top-color:#cd838a}.metric-amber{border-top-color:#c3a26a}.chart-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(270px,1fr);gap:22px}.trend-panel .section-title{align-items:flex-start;margin-bottom:0}.section-title .muted{margin:9px 0 0}.chart-tag{background:#eef6fa;color:#47758e;padding:5px 10px;border-radius:6px;font-size:12px;white-space:nowrap}.health-panel h2{margin-bottom:0}.donut-wrap{position:relative}.donut-wrap :deep(.chart){min-height:210px}.donut-total{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;pointer-events:none}.donut-total strong{font-size:34px}.donut-total span{font-size:12px;color:#6d8395;margin-top:5px}.health-legend{display:grid;gap:10px;font-size:13px}.health-legend>div{display:flex;align-items:center;justify-content:space-between}.health-legend i{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:8px}.product-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.product-card{border:1px solid #dfebf1;border-top:3px solid var(--product-accent);border-radius:14px;padding:20px;min-width:0}.product-card-title{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;min-height:42px}.product-card-title strong{font-size:15px;line-height:1.5;overflow-wrap:anywhere}.color-dot{width:9px;height:9px;border-radius:50%;flex-shrink:0;margin-top:5px}.card-spec,.card-note{font-size:12px;color:#536f82;line-height:1.5;margin:6px 0;overflow-wrap:anywhere}.card-balance{display:flex;justify-content:space-between;align-items:center;margin:18px 0}.card-balance span{font-size:12px;color:#5c7487}.card-balance strong{display:block;font-size:30px;line-height:1.5;font-variant-numeric:tabular-nums}.card-balance small{font-size:12px;font-weight:400;margin-left:8px}.card-flow{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;padding:14px 0;border-top:1px solid #c3d3df66;border-bottom:1px solid #c3d3df66}.card-flow span{display:block;font-size:11px;color:#60778a;margin-bottom:7px}.card-flow b{font-size:17px;font-variant-numeric:tabular-nums}.card-bottom{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:14px}.card-bottom small{font-size:11px;color:#617b8e}@media(min-width:1700px){.product-cards{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:1300px){.filter-grid{grid-template-columns:140px 18px 140px minmax(100px,1fr)}.filter-grid>.product-filter{grid-column:1/4;grid-row:2}.product-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.metric{padding:16px}.metric strong{font-size:29px}}@media(max-width:950px){.chart-grid{grid-template-columns:1fr}.insight-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:620px){.product-cards{grid-template-columns:1fr}.filter-grid{display:flex;flex-wrap:wrap}.filter-grid :deep(.el-date-editor){width:calc(50% - 22px)}.filter-grid .el-select{width:100%}.filter-top{align-items:flex-start;flex-direction:column}.section-title{flex-wrap:wrap}.metric strong{font-size:26px}}
</style>
